// ============================================================================
// CHI_apb: APB4 register wrapper around CHI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CHI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CHI.md
// ============================================================================
module CHI_apb #(
  parameter int LINES = 16,
  // memory, 64-byte lines (power of 2, at most 1024)
  parameter int RQ    = 4,
  // request slots (power of 2, at least 2)
  parameter int NDC   = 2
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxreqflitv,
  input logic [40:0] rxreqflit,
  output logic rxreqlcrdv,
  input logic rxdatflitv,
  input logic [157:0] rxdatflit,
  output logic rxdatlcrdv,
  output logic txrspflitv,
  output logic [28:0] txrspflit,
  input logic txrsplcrdv,
  output logic txdatflitv,
  output logic [146:0] txdatflit,
  input logic txdatlcrdv
);
  localparam logic [31:0] ID_VALUE = 32'h43480200;

  // ---------------- core ----------------
  logic          c_ev_err;
  logic          c_ev_proto;
  CHI_top #(.LINES(LINES), .RQ(RQ), .NDC(NDC)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxreqflitv(rxreqflitv),
    .rxreqflit(rxreqflit),
    .rxreqlcrdv(rxreqlcrdv),
    .rxdatflitv(rxdatflitv),
    .rxdatflit(rxdatflit),
    .rxdatlcrdv(rxdatlcrdv),
    .txrspflitv(txrspflitv),
    .txrspflit(txrspflit),
    .txrsplcrdv(txrsplcrdv),
    .txdatflitv(txdatflitv),
    .txdatflit(txdatflit),
    .txdatlcrdv(txdatlcrdv),
    .ev_err(c_ev_err),
    .ev_proto(c_ev_proto)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_err;
    irq_set[1] = c_ev_proto;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd4: rdata = scratch;
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
